import XCTest
@MainActor final class WritingJourneyTests:XCTestCase {
    private func tap(_ id:String,_ app:XCUIApplication){let e=app.descendants(matching:.any).matching(identifier:id).firstMatch;XCTAssertTrue(e.waitForExistence(timeout:10));for _ in 0..<14 where !e.isHittable{if e.exists,e.frame.midY<app.frame.midY{app.swipeDown(velocity:.slow)}else{app.swipeUp(velocity:.slow)}};if !e.isHittable{shot("Missing writing interaction \(id)",app)};XCTAssertTrue(e.isHittable);e.tap()}
    private func shot(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
    private func launch(_ variant:String,target:String="es",speech:Bool=false)->XCUIApplication {
        let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_HEADLINE_FIXTURE":"failure","PIYALI_PRACTICE_FIXTURE":"delight:"+variant,"PIYALI_PRACTICE_JUDGE_FIXTURE":"offered-reference","PIYALI_WRITING_FIXTURE":"1"];if speech{app.launchEnvironment["PIYALI_WRITING_SPEECH_FIXTURE"]="wrong-then-reference"};app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US","-piyali.interfaceLanguage","en","-piyali.theme","light"];app.launch();handleInitialPaperPencil(app)
        let name=app.textFields["entryName"];XCTAssertTrue(name.waitForExistence(timeout:15));name.tap();name.typeText("Writing Learner");tap("entryKeyboardDone",app);tap("createAccount",app);handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["startLearning"].waitForExistence(timeout:15));tap("onboardingSupport",app);tap("onboardingOption-support-en",app);tap("onboardingPractice",app);tap("onboardingOption-practice-"+target,app);tap("startLearning",app);tap("companionContinue",app);acknowledgePaperPencil(app);tap("gettingStartedGotIt",app);chooseA1Placement(app);tap("productMenu",app);tap("productModeMenu",app);tap("productMode-path",app);if !app.buttons["lessonNode-lesson-pre-a1-1-1"].exists{tap("lessonPreviousLevel",app)}
        // Japanese uses its own authored path, not a Spanish lesson id.
        let first=target == "es" ? app.buttons["lessonNode-lesson-pre-a1-1-1"]:app.buttons.matching(NSPredicate(format:"identifier BEGINSWITH 'lessonNode-' AND enabled == true")).firstMatch
        XCTAssertTrue(first.waitForExistence(timeout:10));for _ in 0..<10 where !first.isHittable{if first.frame.midY<app.frame.midY{app.swipeDown(velocity:.slow)}else{app.swipeUp(velocity:.slow)}};XCTAssertTrue(first.isHittable);first.tap();tap("startLessonFromPreview",app);XCTAssertTrue(app.textFields["typedPracticeAnswer"].waitForExistence(timeout:10));return app
    }
    private func dismissKeyboard(_ app:XCUIApplication){if app.buttons["practiceKeyboardDone"].exists{tap("practiceKeyboardDone",app)}}
    private func replace(_ text:String,_ app:XCUIApplication){let field=app.textFields["typedPracticeAnswer"];field.tap();let old=(field.value as? String) ?? "";if old == "WRONG_FIXTURE"{field.typeText(String(repeating:XCUIKeyboardKey.delete.rawValue,count:old.count))};field.typeText(text)}
    func testTypedTransformationAndThreeCueSentenceRetrySubmitAndAdvance() {
        continueAfterFailure=false
        for(variant,answer)in[("sentence_shapeshifter","Ella cena con su familia."),("three_word_challenge","Ayer fui al parque con mis amigos.")]{
            let app=launch(variant);XCTAssertFalse(app.buttons["writingKeyboardToggle"].exists);replace("WRONG_FIXTURE",app);dismissKeyboard(app);tap("checkTypedAnswer",app);XCTAssertTrue(app.staticTexts["practiceVerdict"].waitForExistence(timeout:10));XCTAssertTrue(app.staticTexts["practiceVerdict"].label.contains("Try again"));replace(answer,app);app.textFields["typedPracticeAnswer"].typeText("\n");XCTAssertTrue(app.buttons["nextTypedQuestion"].waitForExistence(timeout:10));XCTAssertTrue(app.staticTexts["practiceVerdict"].label.contains("+7 XP"));XCTAssertEqual(app.staticTexts["activeLessonXP"].label,"9%");XCTAssertFalse(app.textFields["typedPracticeAnswer"].isEnabled);shot("Native \(variant) typed success",app);tap("nextTypedQuestion",app);XCTAssertTrue(app.textFields["typedPracticeAnswer"].waitForExistence(timeout:10));XCTAssertFalse(app.staticTexts["practiceVerdict"].exists);XCTAssertFalse(app.buttons["checkTypedAnswer"].isEnabled);app.terminate()
        }
    }
    func testCluesReducePotentialXPAndSpeechAutomaticallyRetriesThenEarnsFourXP() {
        continueAfterFailure=false;let app=launch("three_clue_mystery",speech:true)
        XCTAssertTrue(app.staticTexts["writingPotentialXP"].label.contains("10"));tap("writingRevealClue",app);XCTAssertTrue(app.staticTexts["writingPotentialXP"].label.contains("7"));tap("writingRevealClue",app);XCTAssertTrue(app.staticTexts["writingPotentialXP"].label.contains("4"));XCTAssertFalse(app.buttons["writingRevealClue"].exists);XCTAssertFalse(app.staticTexts["practiceVerdict"].exists);shot("Native three clues and four XP potential",app)
        tap("typedPracticeMicrophone",app);XCTAssertTrue(app.staticTexts["practiceVerdict"].waitForExistence(timeout:15));XCTAssertTrue(app.staticTexts["practiceVerdict"].label.contains("Try again"));XCTAssertEqual(app.textFields["typedPracticeAnswer"].value as? String,"WRONG_FIXTURE");tap("typedPracticeMicrophone",app);XCTAssertTrue(app.buttons["nextTypedQuestion"].waitForExistence(timeout:15));XCTAssertTrue(app.staticTexts["practiceVerdict"].label.contains("+4 XP"));XCTAssertEqual(app.staticTexts["activeLessonXP"].label,"5%");XCTAssertEqual(app.textFields["typedPracticeAnswer"].value as? String,"paraguas");XCTAssertFalse(app.buttons["typedPracticeMicrophone"].isEnabled);shot("Native speech answer graded after all clues",app)
    }
    func testJapaneseAndRussianKeyboardsSwitchModesAppendSpaceBackspaceAndClose() {
        continueAfterFailure=false
        for(target,lower,upper)in[("ja","あ","ア"),("ru","а","А")]{let app=launch("three_word_challenge",target:target);tap("writingKeyboardToggle",app);tap("writingKey-0-0",app);XCTAssertEqual(app.textFields["typedPracticeAnswer"].value as? String,lower);tap(target == "ja" ? "writingKeyboardKatakana":"writingKeyboardCase",app);tap("writingKey-0-0",app);XCTAssertEqual(app.textFields["typedPracticeAnswer"].value as? String,lower+upper);tap("writingKeyboardSpace",app);XCTAssertEqual(app.textFields["typedPracticeAnswer"].value as? String,lower+upper+" ");tap("writingKeyboardBackspace",app);tap("writingKeyboardBackspace",app);XCTAssertEqual(app.textFields["typedPracticeAnswer"].value as? String,lower);shot("Native \(target) virtual keyboard text",app);tap("writingKeyboardClose",app);XCTAssertFalse(app.otherElements["writingVirtualKeyboard"].exists);XCTAssertTrue(app.buttons["writingKeyboardToggle"].exists);XCTAssertFalse(app.staticTexts["practiceVerdict"].exists);app.terminate()}
    }
}
